    "$schema": "http://json-schema.org/draft-07/schema#",
    "title": "MARPL rules",
    "definitions": {
        "object-variable": {
            "type": "object",
            "properties": {
                "type": {
                    "type": "string",
                    "const": "variable"
                },
                "name": {
                    "type": "string",
                    "minLength": 1
                }
            },
            "required": [
                "type",
                "name"
            ]
        },
        "object-literal": {
            "type": "object",
            "properties": {
                "type": {
                    "type": "string",
                    "const": "literal"
                },
                "name": {
                    "type": "string",
                    "minLength": 1
                }
            },
            "required": [
                "type",
                "name"
            ]
        },
        "literal-expression": {
            "type": "object",
            "properties": {
                "type": {
                    "type": "string",
                    "const": "literal-expression"
                },
                "name": {
                    "type": "string",
                    "minLength": 1
                }
            },
            "required": [
                "type",
                "name"
            ]
        },
        "object-term": {
            "oneOf": [
                {
                    "$ref": "#/definitions/object-variable"
                },
                {
                    "$ref": "#/definitions/object-literal"
                },
                {
                    "$ref": "#/definitions/literal-expression"
                }
            ]
        },
        "set-literal": {
            "properties": {
                "type": {
                    "type": "string",
                    "const": "set-term"
                },
                "assignments": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {
                            "attribute": {
                                "$ref": "#/definitions/object-term"
                            },
                            "value": {
                                "$ref": "#/definitions/object-term"
                            }
                        },
                        "required": [
                            "attribute",
                            "value"
                        ]
                    },
                    "_uniqueItems": true
                }
            },
            "required": [
                "type",
                "assignments"
            ]
        },
        "set-literal-with-dots": {
            "properties": {
                "type": {
                    "type": "string",
                    "const": "set-term"
                },
                "assignments": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {
                            "attribute": {
                                "$ref": "#/definitions/object-term"
                            },
                            "value": {
                                "oneOf": [
                                    {
                                        "$ref": "#/definitions/object-term"
                                    },
                                    {
                                        "$ref": "#/definitions/dot"
                                    }
                                ]
                            }
                        },
                        "required": [
                            "attribute",
                            "value"
                        ]
                    },
                    "_uniqueItems": true
                }
            },
            "required": [
                "type",
                "assignments"
            ]
        },
        "set-variable": {
            "type": "object",
            "properties": {
                "type": {
                    "type": "string",
                    "const": "set-variable"
                },
                "name": {
                    "type": "string",
                    "minLength": 1
                }
            },
            "required": [
                "type",
                "name"
            ]
        },
        "set-term": {
            "oneOf": [
                {
                    "$ref": "#/definitions/set-literal"
                },
                {
                    "$ref": "#/definitions/set-variable"
                }
            ]
        },
        "set-atom": {
            "type": "object",
            "properties": {
                "type": {
                    "type": "string",
                    "const": "set-atom"
                },
                "attribute": {
                    "$ref": "#/definitions/object-term"
                },
                "value": {
                    "$ref": "#/definitions/object-term"
                },
                "set": {
                    "$ref": "#/definitions/set-term"
                }
            },
            "required": [
                "type",
                "attribute",
                "value",
                "set"
            ]
        },
        "relational-atom-base": {
            "type": "object",
            "properties": {
                "type": {
                    "type": "string",
                    "const": "relational-atom"
                },
                "predicate": {
                    "$ref": "#/definitions/object-term"
                },
                "arguments": {
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/object-term"
                    }
                },
                "annotation": {
                    "type": "object"
                }
            },
            "required": [
                "type",
                "predicate",
                "arguments",
                "annotation"
            ]
        },
        "function-term": {
            "type": "object",
            "properties": {
                "type": {
                    "type": "string",
                    "const": "function-term"
                },
                "name": {
                    "type": "string",
                    "minLength": 1
                },
                "arguments": {
                    "type": "array",
                    "items": {
                        "oneOf": [
                            {
                                "$ref": "#/definitions/object-term"
                            },
                            {
                                "$ref": "#/definitions/set-term"
                            }
                        ]
                    }
                }
            },
            "required": [
                "type",
                "name",
                "arguments"
            ]
        },
        "relational-atom": {
            "type": "object",
            "allOf": [
                {
                    "$ref": "#/definitions/relational-atom-base"
                },
                {
                    "properties": {
                        "annotation": {
                            "$ref": "#/definitions/set-term"
                        }
                    }
                }
            ]
        },
        "relational-atom-with-dots": {
            "type": "object",
            "allOf": [
                {
                    "$ref": "#/definitions/relational-atom-base"
                },
                {
                    "properties": {
                        "annotation": {
                            "oneOf": [
                                {
                                    "$ref": "#/definitions/set-literal-with-dots"
                                },
                                {
                                    "$ref": "#/definitions/set-variable"
                                }
                            ]
                        }
                    }
                }
            ]
        },
        "relational-atom-with-function-term": {
            "type": "object",
            "allOf": [
                {
                    "$ref": "#/definitions/relational-atom-base"
                },
                {
                    "properties": {
                        "annotation": {
                            "$ref": "#/definitions/function-term"
                        }
                    }
                }
            ]
        },
        "placeholder": {
            "type": "object",
            "properties": {
                "type": {
                    "type": "string",
                    "enum": [
                        "star",
                        "plus"
                    ]
                }
            },
            "required": [
                "type"
            ]
        },
        "assignment": {
            "type": "object",
            "properties": {
                "attribute": {
                    "$ref": "#/definitions/object-term"
                },
                "value": {
                    "oneOf": [
                        {
                            "$ref": "#/definitions/object-term"
                        },
                        {
                            "$ref": "#/definitions/placeholder"
                        }
                    ]
                }
            },
            "required": [
                "attribute",
                "value"
            ]
        },
        "dot": {
            "type": "object",
            "properties": {
                "type": {
                    "type": "string",
                    "const": "dot"
                },
                "fromSpecifier": {
                    "$ref": "#/definitions/set-variable"
                },
                "item": {
                    "$ref": "#/definitions/object-literal"
                }
            }
        },
        "specifier": {
            "type": "object",
            "properties": {
                "type": {
                    "type": "string",
                    "enum": [
                        "open-specifier",
                        "closed-specifier"
                    ]
                },
                "assigmnents": {
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/assignment"
                    }
                }
            },
            "required": [
                "type",
                "assignments"
            ]
        },
        "specifier-expression": {
            "type": "object",
            "properties": {
                "type": {
                    "type": "string",
                    "enum": [
                        "union",
                        "intersection",
                        "difference"
                    ]
                },
                "specifiers": {
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/specifier-term"
                    },
                    "minItems": 1
                }
            },
            "required": [
                "type",
                "specifiers"
            ]
        },
        "specifier-term": {
            "oneOf": [
                {
                    "$ref": "#/definitions/specifier"
                },
                {
                    "$ref": "#/definitions/specifier-expression"
                }
            ]
        },
        "specifier-atom": {
            "type": "object",
            "properties": {
                "type": {
                    "type": "string",
                    "const": "specifier-atom"
                },
                "specifier": {
                    "$ref": "#/definitions/specifier-term"
                },
                "set": {
                    "$ref": "#/definitions/set-variable"
                }
            },
            "required": [
                "specifier",
                "set"
            ]
        }
    },
    "type": "object",
    "properties": {
        "type": {
            "type": "string",
            "const": "rule"
        },
        "body": {
            "type": "array",
            "items": {
                "oneOf": [
                    {
                        "$ref": "#/definitions/relational-atom"
                    },
                    {
                        "$ref": "#/definitions/set-atom"
                    },
                    {
                        "$ref": "#/definitions/specifier-atom"
                    }
                ]
            }
        },
        "head": {
            "oneOf": [
                {
                    "$ref": "#/definitions/relational-atom-with-dots"
                },
                {
                    "$ref": "#/definitions/relational-atom-with-function-term"
                }
            ]
        }
    },
    "required": [
        "body",
        "head"
    ]
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "WINNF v1.1 cpiSignatureData object",
    "description": "CPI signed data provided by CBSD in registration request",
    "type": "object",
    "required": [
        "fccId",
        "cbsdSerialNumber",
        "installationParam",
        "professionalInstallerData"
    ],
    "additionalProperties": false,
    "properties": {
        "fccId": {
            "type": "string",
            "maxLength": 128,
            "description": "The certification FCC ID for the hardware"
        },
        "cbsdSerialNumber": {
            "type": "string",
            "maxLength": 128,
            "description": "Unique identifier for the CBSD chosen by the manufacturer"
        },
        "installationParam": {
            "$ref": "#/definitions/installationParam"
        },
        "professionalInstallerData": {
            "$ref": "#/definitions/professionalInstallerData"
        }
    },
    "definitions": {
        "professionalInstallerData": {
            "type": "object",
            "description": "Data identifying the CPI vouching for the installation parameters in this object",
            "required": [
                "cpiId",
                "cpiName",
                "installCertificationTime"
            ],
            "additionalProperties": false,
            "properties": {
                "cpiId": {
                    "type": "string",
                    "maxLength": 256,
                    "description": "ID of CPI providing information to SAS"
                },
                "cpiName": {
                    "type": "string",
                    "maxLength": 256,
                    "description": "Human-readable name of the CPI providing information to the SAS"
                },
                "installCertificationTime": {
                    "type": "string",
                    "maxLength": 64,
                    "description": "UTC date/time at which CPI certified this object.  Format:  YYYY-MM-DDThh:mm:ssZ"
                }
            }
        },
        "installationParam": {
            "type": "object",
            "description": "Air interface parameter for a CBSD",
            "required": [
                "latitude",
                "longitude",
                "height",
                "heightType",
                "indoorDeployment",
                "antennaGain",
                "antennaAzimuth",
                "antennaDowntilt",
                "antennaBeamwidth"
            ],
            "additionalProperties": false,
            "properties": {
                "latitude": {
                    "type": "number",
                    "description": "Latitude in WGS84 coordinates, provided in decimal degrees",
                    "minimum": -90,
                    "maximum": 90
                },
                "longitude": {
                    "type": "number",
                    "description": "Longitude in WGS84 coordinates, provided in decimal degrees",
                    "minimum": -180,
                    "maximum": 180
                },
                "height": {
                    "type": "number",
                    "minimum": 0,
                    "maximum": 1000,
                    "description": "Height of CBSD antenna, provided in meters. See heightType for interpretation."
                },
                "heightType": {
                    "type": "string",
                    "enum": [
                        "AMSL",
                        "AGL"
                    ],
                    "description": "The reference for the height parameter. AMSL indicates the height is measured relative to mean sea level. AGL indicates the height is measured relative to local ground level at latitude, longitude."
                },
                "horizontalAccuracy": {
                    "type": "number",
                    "description": "A measurement in meters of the horizontal accuracy of the indicated location.",
                    "minimum": 0,
                    "maximum": 50
                },
                "verticalAccuracy": {
                    "type": "number",
                    "description": "A measurement in meters of the vertical accuracy of the indicated location.",
                    "minimum": 0,
                    "maximum": 3
                },
                "indoorDeployment": {
                    "type": "boolean",
                    "description": "True if the equipment is installed indoors, false if outdoors"
                },
                "eirpCapability": {
                    "type": "number",
                    "description": "Maximum EIRP of the CBSD in units of dBm/10MHz.",
                    "minimum": -127,
                    "maximum": 47
                },
                "antennaAzimuth": {
                    "type": "number",
                    "description": "Heading of antenna azimuth relative to true north, provided in decimal degrees. Positive indicates easterly.",
                    "minimum": 0,
                    "maximum": 359
                },
                "antennaDowntilt": {
                    "type": "number",
                    "description": "Downtilt of the antenna (vertically down is positive) in decimal degrees.",
                    "minimum": -90,
                    "maximum": 90
                },
                "antennaGain": {
                    "type": "number",
                    "description": "Maximum gain in dB of the antenna along the boresight",
                    "minimum": -127,
                    "maximum": 128
                },
                "antennaBeamwidth": {
                    "type": "number",
                    "description": "Beamwidth to 3dB points of the antenna coverage pattern, provided in decimal degrees and measured at the horizon. A value of 360 indicates an omni-directional antenna.",
                    "minimum": 0,
                    "maximum": 360
                },
                "antennaModel": {
                    "type": "string",
                    "maxLength": 128,
                    "description": "If an external antenna is used, the model of the antenna is optionally provided in this field."
                }
            }
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "Doctrine ORM Entity JSON schema for Xcore Generator",
    "type": "object",
    "definitions": {
        "entity-name": {
            "type": "string",
            "description": "Entity name without namespace",
            "minLength": 1
        },
        "property-name": {
            "type": "string",
            "description": "Property name",
            "minLength": 1
        }
    },
    "properties": {
        "name": {
            "$ref": "#/definitions/entity-name"
        },
        "get": {
            "type": "boolean"
        },
        "set": {
            "type": "boolean"
        },
        "namespace": {
            "type": "string"
        },
        "nullable": {
            "type": "boolean",
            "default": true,
            "description": "All properties are nullable by default."
        },
        "properties": {
            "type": "array",
            "minItems": 1,
            "items": {
                "properties": {
                    "id": {
                        "type": "boolean",
                        "default": true
                    },
                    "generatedValue": {
                        "enum": [
                            "AUTO",
                            "SEQUENCE",
                            "IDENTITY",
                            "UUID",
                            "TABLE",
                            "NONE",
                            "CUSTOM"
                        ],
                        "default": "AUTO"
                    },
                    "sequenceGenerator": {
                        "type": "object",
                        "properties": {
                            "sequenceName": {
                                "type": "string"
                            },
                            "initialValue": {
                                "type": "integer"
                            },
                            "allocationSize": {
                                "type": "integer"
                            }
                        }
                    },
                    "name": {
                        "$ref": "#/definitions/property-name"
                    },
                    "columnName": {
                        "type": "string"
                    },
                    "get": {
                        "enum": [
                            true,
                            false,
                            "has",
                            "is"
                        ],
                        "description": "Whether is getter enabled/getter type"
                    },
                    "set": {
                        "type": "boolean"
                    },
                    "length": {
                        "type": "integer",
                        "minimum": 1
                    },
                    "nullable": {
                        "type": "boolean",
                        "default": true
                    },
                    "type": {
                        "enum": [
                            "string",
                            "integer",
                            "smallint",
                            "bigint",
                            "boolean",
                            "decimal",
                            "date",
                            "time",
                            "datetime",
                            "datetimez",
                            "text",
                            "object",
                            "array",
                            "simple_array",
                            "json_array",
                            "float",
                            "guid",
                            "blob"
                        ]
                    },
                    "manyToOne": {
                        "type": "object",
                        "properties": {
                            "targetEntity": {
                                "type": "string"
                            },
                            "inversedBy": {
                                "type": "string"
                            }
                        },
                        "required": [
                            "targetEntity"
                        ]
                    },
                    "oneToOne": {
                        "type": "object",
                        "properties": {
                            "targetEntity": {
                                "type": "string"
                            },
                            "mappedBy": {
                                "type": "string"
                            },
                            "inversedBy": {
                                "type": "string"
                            }
                        },
                        "required": [
                            "targetEntity"
                        ]
                    },
                    "oneToMany": {
                        "type": "object",
                        "properties": {
                            "targetEntity": {
                                "type": "string"
                            },
                            "mappedBy": {
                                "type": "string"
                            }
                        }
                    },
                    "manyToMany": {
                        "type": "object",
                        "properties": {
                            "targetEntity": {
                                "type": "string"
                            },
                            "inversedBy": {
                                "type": "string"
                            },
                            "mappedBy": {
                                "type": "string"
                            }
                        }
                    },
                    "joinColumn": {
                        "type": "object",
                        "properties": {
                            "name": {
                                "type": "string"
                            },
                            "referencedColumnName": {
                                "type": "string"
                            }
                        }
                    },
                    "asserts": {
                        "type": "array",
                        "_uniqueItems": true,
                        "minItems": 1,
                        "items": {
                            "oneOf": [
                                {
                                    "properties": {
                                        "assert": {
                                            "enum": [
                                                "NotBlank"
                                            ]
                                        },
                                        "message": {
                                            "type": "string"
                                        }
                                    }
                                },
                                {
                                    "properties": {
                                        "assert": {
                                            "enum": [
                                                "Blank"
                                            ]
                                        },
                                        "message": {
                                            "type": "string"
                                        }
                                    }
                                },
                                {
                                    "properties": {
                                        "assert": {
                                            "enum": [
                                                "NotNull"
                                            ]
                                        },
                                        "message": {
                                            "type": "string"
                                        }
                                    }
                                },
                                {
                                    "properties": {
                                        "assert": {
                                            "enum": [
                                                "IsNull"
                                            ]
                                        },
                                        "message": {
                                            "type": "string"
                                        }
                                    }
                                },
                                {
                                    "properties": {
                                        "assert": {
                                            "enum": [
                                                "IsTrue"
                                            ]
                                        },
                                        "message": {
                                            "type": "string"
                                        }
                                    }
                                },
                                {
                                    "properties": {
                                        "assert": {
                                            "enum": [
                                                "IsFalse"
                                            ]
                                        },
                                        "message": {
                                            "type": "string"
                                        }
                                    }
                                },
                                {
                                    "properties": {
                                        "assert": {
                                            "enum": [
                                                "Type"
                                            ]
                                        },
                                        "type": {
                                            "enum": [
                                                "array",
                                                "bool",
                                                "callable",
                                                "float",
                                                "double",
                                                "int",
                                                "integer",
                                                "long",
                                                "null",
                                                "numeric",
                                                "object",
                                                "real",
                                                "resource",
                                                "scalar",
                                                "string",
                                                "alnum",
                                                "alpha",
                                                "cntrl",
                                                "digit",
                                                "graph",
                                                "lower",
                                                "print",
                                                "punct",
                                                "space",
                                                "upper",
                                                "xdigit"
                                            ]
                                        },
                                        "message": {
                                            "type": "string"
                                        }
                                    },
                                    "required": [
                                        "type"
                                    ]
                                },
                                {
                                    "properties": {
                                        "assert": {
                                            "enum": [
                                                "Email"
                                            ]
                                        },
                                        "strict": {
                                            "type": "boolean",
                                            "default": true
                                        },
                                        "checkMX": {
                                            "type": "boolean",
                                            "default": true
                                        },
                                        "checkHost": {
                                            "type": "boolean",
                                            "default": true
                                        },
                                        "message": {
                                            "type": "string"
                                        }
                                    }
                                },
                                {
                                    "properties": {
                                        "assert": {
                                            "enum": [
                                                "Length"
                                            ]
                                        },
                                        "min": {
                                            "type": "integer"
                                        },
                                        "max": {
                                            "type": "integer"
                                        },
                                        "charset": {
                                            "type": "integer",
                                            "default": "UTF-8"
                                        },
                                        "minMessage": {
                                            "type": "string"
                                        },
                                        "maxMessage": {
                                            "type": "string"
                                        },
                                        "exactMessage": {
                                            "type": "string"
                                        }
                                    }
                                },
                                {
                                    "properties": {
                                        "assert": {
                                            "enum": [
                                                "Url"
                                            ]
                                        },
                                        "protocols": {
                                            "type": "array",
                                            "items": {
                                                "type": "string"
                                            }
                                        },
                                        "checkDNS": {
                                            "type": "boolean",
                                            "default": true
                                        },
                                        "message": {
                                            "type": "string"
                                        }
                                    }
                                },
                                {
                                    "properties": {
                                        "assert": {
                                            "enum": [
                                                "Regex"
                                            ]
                                        },
                                        "pattern": {
                                            "type": "string"
                                        },
                                        "htmlPattern": {
                                            "type": [
                                                "string",
                                                "boolean"
                                            ]
                                        },
                                        "match": {
                                            "type": "boolean",
                                            "default": true
                                        },
                                        "message": {
                                            "type": "string"
                                        }
                                    }
                                },
                                {
                                    "properties": {
                                        "assert": {
                                            "enum": [
                                                "Ip"
                                            ]
                                        },
                                        "version": {
                                            "enum": [
                                                "4",
                                                "6",
                                                "all",
                                                "4_no_priv",
                                                "6_no_priv",
                                                "all_no_priv",
                                                "4_no_res",
                                                "6_no_res",
                                                "all_no_res",
                                                "4_public",
                                                "6_public",
                                                "all_public"
                                            ]
                                        },
                                        "message": {
                                            "type": "string"
                                        }
                                    }
                                },
                                {
                                    "properties": {
                                        "assert": {
                                            "enum": [
                                                "Uuid"
                                            ]
                                        },
                                        "message": {
                                            "type": "string"
                                        }
                                    }
                                },
                                {
                                    "properties": {
                                        "assert": {
                                            "enum": [
                                                "Range"
